const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"프린터가 출력을 시작할 준비가 되었는지 빠르게 읽기 전용으로 점검합니다."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"다시 점검"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"점검 중..."}},ready:{t:0,b:{t:2,i:[{t:3}],s:"출력 준비 완료"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"출력 준비 안 됨"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"프린터에 연결할 수 없습니다"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper가 준비되었습니다"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper가 준비되지 않았습니다 (상태: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"진행 중인 출력이 없습니다"}},fail:{t:0,b:{t:2,i:[{t:3,v:"이미 출력이 진행 중입니다 ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"모든 축이 호밍되었습니다"}},fail:{t:0,b:{t:2,i:[{t:3,v:"호밍되지 않은 축이 있습니다 ("},{t:4,k:"axes"},{t:3,v:"); 출력 시작 시 보통 먼저 호밍합니다"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"가이드"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"출력 전 점검 가이드"}},close:{t:0,b:{t:2,i:[{t:3}],s:"닫기"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"출력 전 점검이란?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"프린터가 시작할 준비가 되었는지 읽기 전용으로 살펴봅니다. 아무것도 움직이거나 변경하지 않고 상태만 보고합니다. 치명적인 차단 요소는 결과를 빨간색으로 표시하고, 경고는 정보를 제공하되 차단하지 않습니다."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"점검 항목"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper가 준비되었는지(종료되거나 오류 상태가 아닌지), 이미 진행 중인 출력이 없는지, 그리고 축이 호밍되었는지(출력 시작 시 보통 먼저 호밍하므로 참고용)를 확인합니다."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"용어집"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 상태"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klipper 자체의 상태입니다. 'ready'(준비됨)는 연결되어 대기 중임을 뜻하고, 'shutdown'(종료) 또는 'error'(오류)는 해제하기 전까지 출력할 수 없음을 뜻합니다."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"호밍"}},def:{t:0,b:{t:2,i:[{t:3}],s:"각 축을 엔드스톱으로 이동시켜 프린터가 툴헤드의 위치를 파악하게 하는 동작입니다. 대부분의 출력 시작 루틴은 자동으로 호밍합니다."}}}}}}};export{t as default};
